module tb;

  // ------------------------------------------------------------
  // Clock generation (100 MHz)
  // ------------------------------------------------------------
  reg clk = 0;
  always #(5) clk = ~clk;  // 10 ns period

  // ------------------------------------------------------------
  // DUT interface signals
  // ------------------------------------------------------------
  reg rst = 0;
  reg [15:0] prescale = 16'd1;   // configure DUT with minimum prescale
  reg rxd = 1'b1;
  reg m_axis_tready = 1'b1;

  wire [7:0] m_axis_tdata;
  wire       m_axis_tvalid;
  wire       busy;
  wire       frame_error;
  wire       overrun_error;   // required by the DUT but not used locally

  // ------------------------------------------------------------
  // DUT instantiation
  // ------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk            (clk),
    .rst            (rst),
    .m_axis_tdata   (m_axis_tdata),
    .m_axis_tvalid  (m_axis_tvalid),
    .m_axis_tready  (m_axis_tready),
    .rxd            (rxd),
    .busy           (busy),
    .overrun_error  (overrun_error),
    .frame_error    (frame_error),
    .prescale       (prescale)
  );

  // ------------------------------------------------------------
  // Task: reset the design
  // ------------------------------------------------------------
  task automatic reset;
    rst = 1'b1;
    @(posedge clk);
    repeat (3) @(posedge clk);
    rst = 1'b0;
    @(posedge clk);
    repeat (3) @(posedge clk);
  endtask

  // ------------------------------------------------------------
  // Task: transmit one byte over UART (8‑N‑1) at the currently
  //       configured prescale.  Each bit is held for 12 clocks
  //       (sufficient for the DUT’s bit‑time calculation).
  // ------------------------------------------------------------
  task automatic send_byte(input byte unsigned b);
    // Start bit – low
    rxd = 1'b0;
    repeat (12) @(posedge clk);
    // Data bits – LSB first
    for (int i = 0; i < 8; i = i + 1) begin
      rxd = b[i];
      repeat (12) @(posedge clk);
    end
    // Stop bit – high
    rxd = 1'b1;
    repeat (12) @(posedge clk);
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // 1. Apply reset
    reset();

    // 2. Allow design to come out of reset
    repeat (30) @(posedge clk);

    // 3. Send first frame: 0x69
    send_byte(8'h69);
    // Allow time for the first word to be received and handed off
    repeat (30) @(posedge clk);

    // 4. Send second frame: 0x96 (back‑to‑back, same prescale)
    send_byte(8'h96);
    // Wait long enough for the coverage point to be sampled
    repeat (80) @(posedge clk);

    // 5. Finish simulation – coverage point has been hit
    $finish;
  end

  // ------------------------------------------------------------
  // Initialise stimulus values
  // ------------------------------------------------------------
  initial rxd = 1'b1;

endmodule

module tb;

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic        clk = 0;
  logic        rst   = 1'b1;
  // 8‑bit UART data bus
  logic [7:0]  s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready;
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;
  // UART interface
  logic        rxd;
  // Configuration
  logic [15:0] prescale = 16'd1;   // minimum prescale

  // ------------------------------------------------------------
  // Clock generation (period = 8 time units → 125 MHz)
  // ------------------------------------------------------------
  initial clk = 1'b0;
  always #4 clk = ~clk;

  // ------------------------------------------------------------
  // DUT instantiation (default parameters)
  // ------------------------------------------------------------
  uart dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready),
    .rxd               (rxd),
    .txd               (),          // not used
    .tx_busy           (),
    .rx_busy           (),
    .rx_overrun_error  (),
    .rx_frame_error    (),
    .prescale          (prescale)
  );

  // ------------------------------------------------------------
  // Tie‑off TX side (idle)
  // ------------------------------------------------------------
  assign s_axis_tready = 1'b1;
  assign s_axis_tvalid = 1'b0;
  assign s_axis_tdata  = 8'h00;

  // ------------------------------------------------------------
  // Reset sequence
  // ------------------------------------------------------------
  initial begin
    #100 rst = 1'b1;
    #100 rst = 1'b0;
    #100;
  end

  // ------------------------------------------------------------
  // Task: send one UART frame (start, 8 data bits LSB first, stop)
  // ------------------------------------------------------------
  task automatic send_frame(input byte data);
    // 10 bit periods per frame, each period = 8 clocks (prescale = 1)
    for (int bp = 0; bp < 10; bp++) begin
      if (bp == 0)       rxd <= 1'b0;                     // start bit
      else if (bp >= 1 && bp <= 8)
                         rxd <= data[bp-1];                 // data bits
      else               rxd <= 1'b1;                     // stop bit
      // wait one full bit period (8 clock cycles)
      repeat (8) @(posedge clk);
    end
  endtask

  // ------------------------------------------------------------
  // Apply two back‑to‑back frames: 0x69 then 0x96
  // ------------------------------------------------------------
  initial begin
    @(negedge rst);               // wait for reset de‑assertion
    send_frame(8'h69);            // first word
    send_frame(8'h96);            // second word
    // Allow enough time for the DUT to present m_axis_tvalid=1 with data=0x96
    repeat (2500) @(posedge clk);
    $finish;                      // end simulation cleanly
  end

endmodule
